// ========================================================================
// Step 1: Run subscription detection
// ========================================================================
// This calls the detection logic inline (same algorithm as
// scripts/detect-subscriptions.js) via Plaid transactions already synced
// in Neon.  We do the detection first, then query the results.
//
// Since n8n Code nodes can't import external modules on Community Edition,
// we call the detection script via the Execute Command node instead.
// This Code node just returns a passthrough signal.
// ========================================================================
return [{ json: { trigger: 'digest' } }];

// ========================================================================
// Build the weekly digest email body
// ========================================================================
const subs = $input.all().map(i => i.json);

if (subs.length === 0) {
  return [{ json: { subject: 'Subscription Digest — No Active Subscriptions', body: '<div style="font-family: Inter, system-ui, sans-serif; background: #080b12; color: #f0ebe3; padding: 40px 24px; max-width: 600px; margin: 0 auto;"><h2 style="font-weight: 300; font-size: 28px; letter-spacing: -0.3px;">Weekly Digest</h2><p style="color: rgba(240,235,227,0.5); font-size: 15px; font-weight: 300;">No recurring subscriptions detected yet. Transactions may still be syncing.</p></div>' } }];
}

// Calculate estimated monthly cost
let monthlyTotal = 0;
for (const s of subs) {
  const amt = parseFloat(s.amount);
  if (s.cadence_days <= 35) monthlyTotal += amt;
  else if (s.cadence_days <= 65) monthlyTotal += amt / 2;
  else if (s.cadence_days <= 95) monthlyTotal += amt / 3;
  else monthlyTotal += amt / (s.cadence_days / 30);
}

const newSubs = subs.filter(s => s.is_new);
const changedSubs = subs.filter(s => s.amount_changed);

const fmt = (n) => '$' + parseFloat(n).toFixed(2);
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '\u2014';

// Build HTML — dark aurora-inspired email
let html = `<div style="font-family: Inter, system-ui, -apple-system, sans-serif; background: #080b12; max-width: 600px; margin: 0 auto; border-radius: 12px; overflow: hidden;">`;

// Header with warm gradient accent
html += `<div style="background: linear-gradient(135deg, rgba(200,133,108,0.3) 0%, rgba(90,143,143,0.2) 50%, rgba(8,11,18,1) 100%); padding: 40px 32px 32px;">`;
html += `<p style="font-size: 10px; font-weight: 500; letter-spacing: 2px; text-transform: uppercase; color: rgba(240,235,227,0.4); margin: 0 0 16px;">Subscription Tracker</p>`;
html += `<h1 style="font-size: 32px; font-weight: 300; color: #f0ebe3; margin: 0 0 8px; letter-spacing: -0.5px;">Weekly Digest</h1>`;
html += `<p style="font-size: 15px; color: rgba(240,235,227,0.5); margin: 0; font-weight: 300;">${subs.length} active subscription${subs.length !== 1 ? 's' : ''} tracked</p>`;
html += `</div>`;

// Monthly cost card
html += `<div style="padding: 0 32px;">`;
html += `<div style="background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 20px 24px; margin: 24px 0;">`;
html += `<p style="font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: rgba(240,235,227,0.4); margin: 0 0 6px; font-weight: 500;">Estimated Monthly Cost</p>`;
html += `<p style="font-size: 28px; font-weight: 300; color: #c8856c; margin: 0; letter-spacing: -0.5px;">${fmt(monthlyTotal)}</p>`;
html += `</div>`;

// New subscriptions callout
if (newSubs.length > 0) {
  html += `<div style="background: rgba(111,207,151,0.08); border: 1px solid rgba(111,207,151,0.12); border-radius: 10px; padding: 16px 20px; margin: 16px 0;">`;
  html += `<p style="font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: #6fcf97; margin: 0 0 10px; font-weight: 600;">New This Week</p>`;
  for (const s of newSubs) {
    html += `<p style="font-size: 14px; color: #f0ebe3; margin: 4px 0; font-weight: 300;">${s.display_name} \u2014 ${fmt(s.amount)} every ${s.cadence_days} days</p>`;
  }
  html += `</div>`;
}

// Amount changes callout
if (changedSubs.length > 0) {
  html += `<div style="background: rgba(240,195,109,0.08); border: 1px solid rgba(240,195,109,0.12); border-radius: 10px; padding: 16px 20px; margin: 16px 0;">`;
  html += `<p style="font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: #f0c36d; margin: 0 0 10px; font-weight: 600;">Price Changes</p>`;
  for (const s of changedSubs) {
    const delta = parseFloat(s.amount) - parseFloat(s.prior_amount);
    const arrow = delta > 0 ? '\u2191' : '\u2193';
    html += `<p style="font-size: 14px; color: #f0ebe3; margin: 4px 0; font-weight: 300;">${s.display_name}: ${fmt(s.prior_amount)} \u2192 ${fmt(s.amount)} <span style="color: ${delta > 0 ? '#eb6b6b' : '#6fcf97'};">(${arrow}${fmt(Math.abs(delta))})</span></p>`;
  }
  html += `</div>`;
}

// Full table
html += `<table style="width: 100%; border-collapse: collapse; margin: 24px 0;">`;
html += `<tr><th style="text-align: left; padding: 10px 12px; font-size: 9px; letter-spacing: 1.5px; text-transform: uppercase; color: rgba(240,235,227,0.4); font-weight: 500; border-bottom: 1px solid rgba(255,255,255,0.08);">Subscription</th><th style="padding: 10px 12px; font-size: 9px; letter-spacing: 1.5px; text-transform: uppercase; color: rgba(240,235,227,0.4); font-weight: 500; border-bottom: 1px solid rgba(255,255,255,0.08);">Amount</th><th style="padding: 10px 12px; font-size: 9px; letter-spacing: 1.5px; text-transform: uppercase; color: rgba(240,235,227,0.4); font-weight: 500; border-bottom: 1px solid rgba(255,255,255,0.08);">Cycle</th><th style="padding: 10px 12px; font-size: 9px; letter-spacing: 1.5px; text-transform: uppercase; color: rgba(240,235,227,0.4); font-weight: 500; border-bottom: 1px solid rgba(255,255,255,0.08);">Next Charge</th></tr>`;
for (const s of subs) {
  const cadenceLabel = s.cadence_days <= 35 ? 'Monthly' : s.cadence_days <= 65 ? 'Bi-monthly' : s.cadence_days <= 95 ? 'Quarterly' : s.cadence_days <= 370 ? 'Yearly' : s.cadence_days + 'd';
  html += `<tr>`;
  html += `<td style="padding: 12px; font-size: 14px; font-weight: 300; color: #f0ebe3; border-bottom: 1px solid rgba(255,255,255,0.04);">${s.display_name}</td>`;
  html += `<td style="padding: 12px; font-size: 14px; font-weight: 400; color: #d4a574; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.04);">${fmt(s.amount)}</td>`;
  html += `<td style="padding: 12px; font-size: 13px; font-weight: 300; color: rgba(240,235,227,0.5); text-align: center; border-bottom: 1px solid rgba(255,255,255,0.04);">${cadenceLabel}</td>`;
  html += `<td style="padding: 12px; font-size: 13px; font-weight: 300; color: rgba(240,235,227,0.5); text-align: center; border-bottom: 1px solid rgba(255,255,255,0.04);">${fmtDate(s.next_expected)}</td>`;
  html += `</tr>`;
}
html += `</table>`;
html += `</div>`;

// Footer
html += `<div style="padding: 24px 32px 32px; border-top: 1px solid rgba(255,255,255,0.06);">`;
html += `<p style="color: rgba(240,235,227,0.3); font-size: 11px; margin: 0; font-weight: 300; letter-spacing: 0.3px;">Generated by Subscription Tracker</p>`;
html += `</div>`;
html += `</div>`;

// Reset is_new and amount_changed flags after digest
const resetSql = `UPDATE detected_subscriptions SET is_new = false, amount_changed = false WHERE is_active = true;`;

return [{ json: {
  subject: `Subscription Digest \u2014 ${subs.length} active, ${fmt(monthlyTotal)}/mo`,
  body: html,
  resetSql,
  subCount: subs.length,
  monthlyTotal: monthlyTotal.toFixed(2),
} }];
